  async updateUser(id,f){ const u=data.users.find(x=>x.id===Number(id)); if(!u) return null; if(f.status) u.status=f.status; if(f.name) u.name=f.name; if(f.role) u.role=f.role; if(f.username!==undefined) u.username=f.username; if(f.email!==undefined) u.email=f.email; if(f.password_hash){ u.password_hash=f.password_hash; u.password_salt=f.password_salt; } saveJson(); return u; },
